window.WALKTHROUGH_CUES = [{"s":0.7,"e":10.5,"t":"Welcome to the Review Desk. A colleague has drafted four handouts with AI, and you will audit them before they reach students."},{"s":11.4,"e":17.43,"t":"Open Review Desk, choose Import, and pick a handout from your Handouts folder."},{"s":18.33,"e":24.83,"t":"Each file is scanned first. Scanning only loads the text; it does not check anything."},{"s":25.73,"e":29.73,"t":"Run Check accuracy to see whether the facts hold up."},{"s":30.63,"e":41.32,"t":"Then run Check representation, to see whose contexts and examples are included. The two checks are separate, and you need both."},{"s":42.22,"e":47.68,"t":"Now make your own call. Choose the verdict that fits both findings, and save it."},{"s":48.58,"e":57.06,"t":"Where a handout needs work, write a specific fix. Name the example, or state the corrected fact."},{"s":57.97,"e":64.08,"t":"Your audit report keeps every verdict and fix exactly as you recorded them."},{"s":64.98,"e":71.56,"t":"Take your time; nothing here is timed. When you are ready, choose Start review."}];
